public str getName()
{
    return fieldPName(InventTable, CommissionGroupId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventTable inventTable;
    while select CommissionGroupId from inventTable
        group by CommissionGroupId
    {
        ret.add(inventTable.CommissionGroupId);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, CommissionGroupId));
    qbr.value(queryValue(_value));
}
